package app

import app.repositories.AuditLogRepository
import app.repositories.CategoryRepository
import app.repositories.CustomerRepository
import app.repositories.OrderLineRepository
import app.repositories.OrderRepository
import app.repositories.ProductRepository
import app.repositories.ProductTagRepository
import app.repositories.SqlAuditLogRepository
import app.repositories.SqlCategoryRepository
import app.repositories.SqlCustomerRepository
import app.repositories.SqlOrderLineRepository
import app.repositories.SqlOrderRepository
import app.repositories.SqlProductRepository
import app.repositories.SqlProductTagRepository
import app.repositories.SqlTagRepository
import app.repositories.TagRepository
import java.sql.Connection

/** The repositories over one connection, and its transaction. */
class SqlUnitOfWork(val connection: Connection) : UnitOfWork {
    override val customers: CustomerRepository = SqlCustomerRepository(connection)
    override val categories: CategoryRepository = SqlCategoryRepository(connection)
    override val products: ProductRepository = SqlProductRepository(connection)
    override val orders: OrderRepository = SqlOrderRepository(connection)
    override val orderLines: OrderLineRepository = SqlOrderLineRepository(connection)
    override val tags: TagRepository = SqlTagRepository(connection)
    override val productTags: ProductTagRepository = SqlProductTagRepository(connection)
    override val auditLog: AuditLogRepository = SqlAuditLogRepository(connection)

    /** Joins the transaction already open, or opens one. */
    override fun <T> transaction(work: (UnitOfWork) -> T): T {
        // Joins the transaction already open
        if (!connection.autoCommit) return work(this)
        connection.autoCommit = false
        try {
            val result = work(this)
            connection.commit()
            return result
        } catch (error: Throwable) {
            connection.rollback()
            throw error
        } finally {
            connection.autoCommit = true
        }
    }
}

