package app.services

import app.UnitOfWork
import app.common.CursorPage
import app.dtos.ProductCreate
import app.dtos.ProductRead
import app.dtos.ProductUpdate
import app.entities.Product
import app.entities.ProductTag
import app.errors.ConflictException
import app.errors.FieldError
import app.errors.NotFoundException
import app.errors.ValidationFailedException
import java.math.BigDecimal
import java.time.OffsetDateTime

/** Operations on products. Each write runs in its own transaction. */
class ProductService(private val unitOfWork: UnitOfWork) {
    /** Stores a new Product after checking it. */
    fun createProduct(data: ProductCreate): ProductRead {
        val values = mapOf(
            "categoryId" to data.categoryId,
            "name" to data.name,
            "price" to data.price,
            "status" to data.status,
            "version" to data.version,
            "deletedAt" to data.deletedAt,
        ).filterValues { it != null }
        return unitOfWork.transaction { uow ->
            checkValues(uow, values, null)
            val entity = Product()
            applyValues(entity, values)
            read(uow.products.insert(entity))
        }
    }

    /** The Product with this key; NotFoundException when there is none. */
    fun getProduct(id: Long): ProductRead = read(find(unitOfWork, id))

    /** A page of products after the key after (null for the first page), by primary key. */
    fun listProducts(after: List<Any>?, limit: Int): CursorPage<ProductRead> = unitOfWork.products.list(after, limit).map { read(it) }

    /** Changes the given values of a Product, read at version. */
    fun updateProduct(id: Long, changes: ProductUpdate, version: Int): ProductRead {
        val values = given(changes)
        return unitOfWork.transaction { uow ->
            val current = find(uow, id)
            if (current.version != version)
                throw ConflictException("Product", "was changed by someone else since it was read", listOf("version"))
            checkValues(uow, values, current)
            applyValues(current, values)
            current.version = version + 1
            read(uow.products.update(current))
        }
    }

    /** Marks a Product as deleted (deleted_at); reads leave it out from then on. */
    fun deleteProduct(id: Long, version: Int) {
        unitOfWork.transaction { uow ->
            val current = find(uow, id)
            if (current.version != version)
                throw ConflictException("Product", "was changed by someone else since it was read", listOf("version"))
            if (uow.orderLines.listByProductId(current.id!!).isNotEmpty())
                throw ConflictException("Product", "rows of order_lines still point to it", listOf("order_lines"))
            current.deletedAt = OffsetDateTime.now()
            uow.products.update(current)
        }
    }

    /** The products with this category_id. */
    fun listProductsByCategoryId(categoryId: Long): List<ProductRead> = unitOfWork.products.listByCategoryId(categoryId).map { read(it) }

    /** Links a Product and a Tag (product_tags). */
    fun addTag(productId: Long, tagId: Long) {
        unitOfWork.transaction { uow ->
            find(uow, productId)
            if (uow.tags.findById(tagId) == null)
                throw NotFoundException("Tag", tagId)
            if (uow.productTags.findByProductIdAndTagId(productId, tagId) != null)
                throw ConflictException("Product", "is already linked to this Tag", listOf("tagId"))
            uow.productTags.insert(ProductTag(productId = productId, tagId = tagId))
        }
    }

    /** Removes the link between a Product and a Tag (product_tags). */
    fun removeTag(productId: Long, tagId: Long) {
        unitOfWork.transaction { uow ->
            val link = uow.productTags.findByProductIdAndTagId(productId, tagId) ?: throw NotFoundException("ProductTag", listOf(productId, tagId))
            uow.productTags.delete(link)
        }
    }

    /** Checks the values against the rules of the "products" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private fun validate(uow: UnitOfWork, values: Map<String, Any?>, current: Product?) {
        val creating = current == null
        val errors = mutableListOf<FieldError>()
        run {
            val value = values["categoryId"]
            if (value == null) {
                if (creating || "categoryId" in values) errors += FieldError("category_id", "is required")
            }
        }
        run {
            val value = values["name"]
            if (value == null) {
                if (creating || "name" in values) errors += FieldError("name", "is required")
            } else {
                if (value is String && value.length > 100) errors += FieldError("name", "is longer than 100 characters")
            }
        }
        run {
            val value = values["price"]
            if (value == null) {
                if (creating || "price" in values) errors += FieldError("price", "is required")
            } else {
                if (!((value as Number).toDouble() >= 0.0)) errors += FieldError("price", "must be >= 0")
            }
        }
        run {
            val value = values["status"]
            if (value == null) {
                if (creating || "status" in values) errors += FieldError("status", "is required")
            } else {
                if (value is String && value.length > 10) errors += FieldError("status", "is longer than 10 characters")
            }
        }
        run {
            val value = values["version"]
            if (value == null) {
                if (!creating && "version" in values) errors += FieldError("version", "cannot be empty")
            }
        }
        run {
            val categoryId = if ("categoryId" in values) values["categoryId"] as Long? else current?.categoryId
            if (categoryId != null && uow.categories.findById(categoryId) == null)
                errors += FieldError("category_id", "no Category has this key")
        }
        if (errors.isNotEmpty()) throw ValidationFailedException("Product", errors)
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private fun checkValues(uow: UnitOfWork, values: Map<String, Any?>, current: Product?) {
        validate(uow, values, current)
    }

    /** Sets the given values on the entity. */
    private fun applyValues(entity: Product, values: Map<String, Any?>) {
        if ("categoryId" in values) entity.categoryId = values["categoryId"] as Long?
        if ("name" in values) entity.name = values["name"] as String?
        if ("price" in values) entity.price = values["price"] as BigDecimal?
        if ("status" in values) entity.status = values["status"] as String?
        if ("version" in values) entity.version = values["version"] as Int?
        if ("deletedAt" in values) entity.deletedAt = values["deletedAt"] as OffsetDateTime?
    }

    /** The Product with this key; NotFoundException when there is none. */
    private fun find(uow: UnitOfWork, id: Long): Product =
        uow.products.findById(id) ?: throw NotFoundException("Product", id)

    /** The Product as services return it. */
    private fun read(entity: Product): ProductRead =
        ProductRead(
            id = entity.id!!,
            categoryId = entity.categoryId!!,
            name = entity.name!!,
            price = entity.price!!,
            status = entity.status!!,
            version = entity.version!!,
            deletedAt = entity.deletedAt,
        )

    /** The values an update gives, by field. */
    private fun given(changes: ProductUpdate): Map<String, Any?> {
        val values = mutableMapOf<String, Any?>()
        if (changes.categoryId.isPresent) values["categoryId"] = changes.categoryId.value
        if (changes.name.isPresent) values["name"] = changes.name.value
        if (changes.price.isPresent) values["price"] = changes.price.value
        if (changes.status.isPresent) values["status"] = changes.status.value
        if (changes.version.isPresent) values["version"] = changes.version.value
        if (changes.deletedAt.isPresent) values["deletedAt"] = changes.deletedAt.value
        return values
    }
}

